using System;using System.Data;using System.Linq;namespace AQOONHUB_SMS.Modules.Reports{public partial class ReportAuditLog:ReportStage5Base{protected void Page_Load(object o,EventArgs e){if(!Require(ReportAuthorization.AuditLog))return;if(!IsPostBack){var d=Repo.GetReportAudit(CurrentUserId,CurrentRole);foreach(DataRow r in d.Rows)r["FilterSummary"]=Redact(Convert.ToString(r["FilterSummary"]));gv.DataSource=d;gv.DataBind();litTotal.Text=d.Rows.Count.ToString();litSuccess.Text=d.Select("ResultStatus='Success'").Length.ToString();litFailed.Text=d.Select("ResultStatus<>'Success'").Length.ToString();litExports.Text=d.AsEnumerable().Count(r=>Convert.ToString(r["Action"]).IndexOf("Export",StringComparison.OrdinalIgnoreCase)>=0).ToString();litSchedules.Text=d.AsEnumerable().Count(r=>Convert.ToString(r["Action"]).IndexOf("Schedule",StringComparison.OrdinalIgnoreCase)>=0).ToString();litSaved.Text=d.AsEnumerable().Count(r=>Convert.ToString(r["Action"]).IndexOf("Saved",StringComparison.OrdinalIgnoreCase)>=0).ToString();}}static string Redact(string s){if(string.IsNullOrWhiteSpace(s))return s;string x=s.ToLowerInvariant();return x.Contains("salary")||x.Contains("payment")||x.Contains("medical")||x.Contains("password")||x.Contains("token")||x.Contains("search=")?"Sensitive filter details withheld":s;}}}
